#!/usr/bin/env python3
"""Generates the enumerated parts of bch/PROOF.bend.

PROOF.bend keeps its hand-written lemmas; the parts between
'# BEGIN GENERATED by gen/proof.py: <name>' and '# END GENERATED: <name>'
are rewritten by this script:

  small7   the (7,4) code's laws, by trying every message of up to 4 bits
           and every position of the flipped bit;
  small15  the (15,7) code's laws, by trying every message of up to 7 bits.

Each tried case is computed in a def of its own (the proof kernel has a
step budget per def); the law's def only takes the message apart.

Usage: python3 gen/proof.py   (from bch/)
"""
import itertools, os

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
R = "Result<&2, &2, E.BchError, List<&2, Bool>>"
L = "List<&2, U32>"


def lit(bits):
    return "[%s]" % ", ".join("True{}" if b else "False{}" for b in bits)


def pat(bits):
    out = "Nil{}"
    for b in reversed(bits):
        out = "Con{%s, %s}" % ("True{}" if b else "False{}", out)
    return out


def name(bits):
    return "".join(str(b) for b in bits) if bits else "e"


def messages(lo, hi):
    for n in range(lo, hi + 1):
        for bits in itertools.product((0, 1), repeat=n):
            yield list(bits)


def longer(n):
    """a pattern for the lists of more than n elements"""
    out = "r"
    for i in reversed(range(n + 1)):
        out = "Con{x%d, %s}" % (i, out)
    return out


def gen_small7():
    c = "C.Bch.bch7_4()"
    out = []
    for m in messages(0, 4):
        out.append("def bchp.s7s_%s() -> {S.Bch.syndromes(%s, E.Bch.codeword(%s, %s)) == [0, 0] : %s}:\n  {==}\n" % (name(m), c, c, lit(m), L))
    out.append("def Laws.small7_syndromes(m, short):\n  match m:")
    for m in messages(0, 4):
        out.append("    case %s:\n      bchp.s7s_%s()" % (pat(m), name(m)))
    out.append("    case %s:\n      Empty.absurd({S.Bch.syndromes(%s, E.Bch.codeword(%s, %s)) == [0, 0] : %s}, bchp.ft(short))\n" % (longer(4), c, c, longer(4), L))
    for m in messages(1, 4):
        out.append("def bchp.s7r_%s() -> {D.Bch.decode_bits(%s, E.Bch.codeword(%s, %s)) == Done{%s} : %s}:\n  {==}\n" % (name(m), c, c, lit(m), lit(m), R))
    out.append("def Laws.small7_roundtrip(m, short, some):\n  match m:")
    out.append("    case Nil{}:\n      Empty.absurd({D.Bch.decode_bits(%s, E.Bch.codeword(%s, Nil{})) == Done{Nil{}} : %s}, bchp.ft(some))" % (c, c, R))
    for m in messages(1, 4):
        out.append("    case %s:\n      bchp.s7r_%s()" % (pat(m), name(m)))
    out.append("    case %s:\n      Empty.absurd({D.Bch.decode_bits(%s, E.Bch.codeword(%s, %s)) == Done{%s} : %s}, bchp.ft(short))\n" % (longer(4), c, c, longer(4), longer(4), R))
    for m in messages(1, 4):
        npos = len(m) + 3
        cw = "E.Bch.codeword(%s, %s)" % (c, lit(m))
        for i in range(npos):
            out.append("def bchp.s7e_%s_%d() -> {D.Bch.decode_bits(%s, D.Bch.flip_at(%s, %dn)) == Done{%s} : %s}:\n  {==}\n" % (name(m), i, c, cw, i, lit(m), R))

        def goal(I):
            return "{D.Bch.decode_bits(%s, D.Bch.flip_at(%s, %s)) == Done{%s} : %s}" % (c, cw, I, lit(m), R)
        out.append("def bchp.s7e_%s(i: Nat, inside: {Nat.is_lt(i, Nat.add(List.length(&2, Bool, %s), 3n)) == True{} : Bool}) -> %s:\n  match i:" % (name(m), lit(m), goal("i")))
        for i in range(npos):
            out.append("    case %dn:\n      bchp.s7e_%s_%d()" % (i, name(m), i))
        out.append("    case %dn:\n      Empty.absurd(%s, bchp.ft(inside))" % (npos, goal("%dn" % npos)))
        out.append("    case %dn+k:\n      Empty.absurd(%s, bchp.ft(inside))\n" % (npos + 1, goal("%dn+k" % (npos + 1))))
    out.append("def Laws.small7_error(m, i, short, some, inside):\n  match m:")
    out.append("    case Nil{}:\n      Empty.absurd({D.Bch.decode_bits(%s, D.Bch.flip_at(E.Bch.codeword(%s, Nil{}), i)) == Done{Nil{}} : %s}, bchp.ft(some))" % (c, c, R))
    for m in messages(1, 4):
        out.append("    case %s:\n      bchp.s7e_%s(i, inside)" % (pat(m), name(m)))
    out.append("    case %s:\n      Empty.absurd({D.Bch.decode_bits(%s, D.Bch.flip_at(E.Bch.codeword(%s, %s), i)) == Done{%s} : %s}, bchp.ft(short))\n" % (longer(4), c, c, longer(4), longer(4), R))
    return "\n".join(out)


def gen_small15():
    c = "C.Bch.bch15_7()"
    z = "[0, 0, 0, 0]"
    out = []
    for m in messages(0, 7):
        out.append("def bchp.s15s_%s() -> {S.Bch.syndromes(%s, E.Bch.codeword(%s, %s)) == %s : %s}:\n  {==}\n" % (name(m), c, c, lit(m), z, L))
    out.append("def Laws.small15_syndromes(m, short):\n  match m:")
    for m in messages(0, 7):
        out.append("    case %s:\n      bchp.s15s_%s()" % (pat(m), name(m)))
    out.append("    case %s:\n      Empty.absurd({S.Bch.syndromes(%s, E.Bch.codeword(%s, %s)) == %s : %s}, bchp.ft(short))\n" % (longer(7), c, c, longer(7), z, L))
    for m in messages(1, 7):
        out.append("def bchp.s15r_%s() -> {D.Bch.decode_bits(%s, E.Bch.codeword(%s, %s)) == Done{%s} : %s}:\n  {==}\n" % (name(m), c, c, lit(m), lit(m), R))
    out.append("def Laws.small15_roundtrip(m, short, some):\n  match m:")
    out.append("    case Nil{}:\n      Empty.absurd({D.Bch.decode_bits(%s, E.Bch.codeword(%s, Nil{})) == Done{Nil{}} : %s}, bchp.ft(some))" % (c, c, R))
    for m in messages(1, 7):
        out.append("    case %s:\n      bchp.s15r_%s()" % (pat(m), name(m)))
    out.append("    case %s:\n      Empty.absurd({D.Bch.decode_bits(%s, E.Bch.codeword(%s, %s)) == Done{%s} : %s}, bchp.ft(short))\n" % (longer(7), c, c, longer(7), longer(7), R))
    return "\n".join(out)


SECTIONS = {"small7": gen_small7, "small15": gen_small15}


def main():
    path = os.path.join(HERE, "PROOF.bend")
    text = open(path).read()
    for nm, fn in SECTIONS.items():
        begin = "# BEGIN GENERATED by gen/proof.py: %s\n" % nm
        end = "# END GENERATED: %s\n" % nm
        i, j = text.find(begin), text.find(end)
        if i < 0 or j < 0:
            raise SystemExit("PROOF.bend has no section " + nm)
        text = text[:i + len(begin)] + fn().rstrip("\n") + "\n" + text[j:]
    with open(path, "w", newline="\n") as f:
        f.write(text)


main()
